  1	package com.pousada;
  2	
  3	import com.pousada.api.ApiController;
  4	import com.pousada.repository.Database;
  5	import io.javalin.Javalin;
  6	
  7	public class Main {
  8	    public static void main(String[] args) {
  9	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 10	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 11	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 12	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 13	
 14	        Database.init(dbUrl, dbUser, dbPassword);
 15	
 16	        Javalin app = Javalin.create(config -> {
 17	            config.http.defaultContentType = "application/json";
 18	        }).start(port);
 19	
 20	        ApiController controller = new ApiController();
 21	        controller.registerRoutes(app);
 22	
 23	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
 24	        System.out.println("Servidor rodando na porta " + port);
 25	
 26	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 27	            app.stop();
 28	            Database.close();
 29	        }));
 30	    }
 31	}
 32	package com.pousada.api;
 33	
 34	import com.fasterxml.jackson.databind.ObjectMapper;
 35	import com.fasterxml.jackson.databind.SerializationFeature;
 36	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 37	import com.pousada.domain.*;
 38	import com.pousada.repository.*;
 39	import com.pousada.service.*;
 40	import io.javalin.Javalin;
 41	import io.javalin.http.Context;
 42	import java.math.BigDecimal;
 43	import java.time.LocalDate;
 44	import java.time.YearMonth;
 45	import java.time.format.DateTimeFormatter;
 46	import java.time.format.DateTimeParseException;
 47	import java.util.LinkedHashMap;
 48	import java.util.List;
 49	import java.util.Map;
 50	import java.util.stream.Collectors;
 51	
 52	public class ApiController {
 53	    private final ObjectMapper objectMapper;
 54	    private final RoomRepository roomRepository;
 55	    private final ReservationService reservationService;
 56	    private final MessageService messageService;
 57	    private final ReportService reportService;
 58	
 59	    public ApiController() {
 60	        this.objectMapper = new ObjectMapper();
 61	        this.objectMapper.registerModule(new JavaTimeModule());
 62	        this.objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 63	
 64	        this.roomRepository = new RoomRepository();
 65	        ReservationRepository reservationRepository = new ReservationRepository();
 66	        MessageRepository messageRepository = new MessageRepository();
 67	
 68	        this.messageService = new MessageService(messageRepository);
 69	        this.reservationService = new ReservationService(reservationRepository, roomRepository, messageService);
 70	        this.reportService = new ReportService(reservationRepository, roomRepository);
 71	    }
 72	
 73	    public void registerRoutes(Javalin app) {
 74	        app.get("/rooms", this::getRooms);
 75	        app.post("/reservations", this::createReservation);
 76	        app.get("/reservations/{id}", this::getReservation);
 77	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
 78	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
 79	        app.post("/reservations/{id}/check-in", this::checkInReservation);
 80	        app.post("/reservations/{id}/check-out", this::checkOutReservation);
 81	        app.get("/reservations/{id}/document", this::getDocument);
 82	        app.get("/messages", this::getMessages);
 83	        app.get("/reports/occupancy", this::getOccupancyReport);
 84	        app.get("/reports/revenue", this::getRevenueReport);
 85	
 86	        app.exception(InvalidRequestException.class, (e, ctx) ->
 87	            sendError(ctx, 400, "INVALID_REQUEST", e.getMessage()));
 88	        app.exception(RoomNotFoundException.class, (e, ctx) ->
 89	            sendError(ctx, 404, "ROOM_NOT_FOUND", e.getMessage()));
 90	        app.exception(ReservationNotFoundException.class, (e, ctx) ->
 91	            sendError(ctx, 404, "RESERVATION_NOT_FOUND", e.getMessage()));
 92	        app.exception(RoomUnavailableException.class, (e, ctx) ->
 93	            sendError(ctx, 409, "ROOM_UNAVAILABLE", e.getMessage()));
 94	        app.exception(OperationNotAllowedException.class, (e, ctx) ->
 95	            sendError(ctx, 409, "OPERATION_NOT_ALLOWED", e.getMessage()));
 96	        app.exception(CapacityExceededException.class, (e, ctx) ->
 97	            sendError(ctx, 422, "CAPACITY_EXCEEDED", e.getMessage()));
 98	    }
 99	
100	    private void getRooms(Context ctx) {
101	        List<Room> rooms = roomRepository.findAll();
102	        List<Map<String, Object>> response = rooms.stream()
103	            .map(room -> {
104	                Map<String, Object> map = new LinkedHashMap<>();
105	                map.put("number", room.getNumber());
106	                map.put("type", room.getType().name());
107	                map.put("capacity", room.getCapacity());
108	                map.put("nightlyRate", room.getNightlyRate());
109	                return map;
110	            })
111	            .collect(Collectors.toList());
112	        ctx.json(response);
113	    }
114	
115	    private void createReservation(Context ctx) {
116	        try {
117	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
118	
119	            validateRequiredFields(body, "roomNumber", "guestName", "guestEmail", "guestCpf",
120	                                  "checkIn", "checkOut", "guests", "ratePlan");
121	
122	            Reservation reservation = new Reservation();
123	            reservation.setRoomNumber((String) body.get("roomNumber"));
124	            reservation.setGuestName((String) body.get("guestName"));
125	            reservation.setGuestEmail((String) body.get("guestEmail"));
126	            reservation.setGuestCpf((String) body.get("guestCpf"));
127	
128	            reservation.setCheckIn(parseDate((String) body.get("checkIn")));
129	            reservation.setCheckOut(parseDate((String) body.get("checkOut")));
130	            reservation.setGuests(((Number) body.get("guests")).intValue());
131	            reservation.setRatePlanType(RatePlanType.valueOf((String) body.get("ratePlan")));
132	            reservation.setCompanyCode((String) body.get("companyCode"));
133	
134	            Reservation saved = reservationService.createReservation(reservation);
135	            ctx.status(201).json(toReservationResponse(saved));
136	        } catch (IllegalArgumentException | DateTimeParseException e) {
137	            throw new InvalidRequestException("Dados da requisição inválidos");
138	        }
139	    }
140	
141	    private void getReservation(Context ctx) {
142	        Long id = ctx.pathParamAsClass("id", Long.class).get();
143	        Reservation reservation = reservationService.findById(id);
144	        ctx.json(toReservationResponse(reservation));
145	    }
146	
147	    private void confirmReservation(Context ctx) {
148	        Long id = ctx.pathParamAsClass("id", Long.class).get();
149	        Reservation reservation = reservationService.confirm(id);
150	        ctx.json(toReservationResponse(reservation));
151	    }
152	
153	    private void cancelReservation(Context ctx) {
154	        Long id = ctx.pathParamAsClass("id", Long.class).get();
155	        Reservation reservation = reservationService.cancel(id);
156	        ctx.json(toReservationResponse(reservation));
157	    }
158	
159	    private void checkInReservation(Context ctx) {
160	        Long id = ctx.pathParamAsClass("id", Long.class).get();
161	        Reservation reservation = reservationService.checkIn(id);
162	        ctx.json(toReservationResponse(reservation));
163	    }
164	
165	    private void checkOutReservation(Context ctx) {
166	        Long id = ctx.pathParamAsClass("id", Long.class).get();
167	        Reservation reservation = reservationService.checkOut(id);
168	        ctx.json(toDocumentResponse(reservation));
169	    }
170	
171	    private void getDocument(Context ctx) {
172	        Long id = ctx.pathParamAsClass("id", Long.class).get();
173	        Reservation reservation = reservationService.findById(id);
174	
175	        if (!reservation.isPaid()) {
176	            throw new OperationNotAllowedException("Comprovante disponível apenas para reservas pagas");
177	        }
178	
179	        ctx.json(toDocumentResponse(reservation));
180	    }
181	
182	    private void getMessages(Context ctx) {
183	        List<Message> messages = messageService.findAll();
184	        List<Map<String, Object>> response = messages.stream()
185	            .map(msg -> {
186	                Map<String, Object> map = new LinkedHashMap<>();
187	                map.put("id", msg.getId());
188	                map.put("channel", msg.getChannel());
189	                map.put("to", msg.getTo());
190	                map.put("subject", msg.getSubject());
191	                map.put("body", msg.getBody());
192	                return map;
193	            })
194	            .collect(Collectors.toList());
195	        ctx.json(response);
196	    }
197	
198	    private void getOccupancyReport(Context ctx) {
199	        String dateStr = ctx.queryParam("date");
200	        if (dateStr == null) {
201	            throw new InvalidRequestException("Parâmetro 'date' é obrigatório");
202	        }
203	
204	        try {
205	            LocalDate date = LocalDate.parse(dateStr);
206	            String csv = reportService.generateOccupancyReport(date);
207	            ctx.contentType("text/csv; charset=utf-8").result(csv);
208	        } catch (DateTimeParseException e) {
209	            throw new InvalidRequestException("Formato de data inválido");
210	        }
211	    }
212	
213	    private void getRevenueReport(Context ctx) {
214	        String monthStr = ctx.queryParam("month");
215	        if (monthStr == null) {
216	            throw new InvalidRequestException("Parâmetro 'month' é obrigatório");
217	        }
218	
219	        try {
220	            YearMonth yearMonth = YearMonth.parse(monthStr);
221	            String csv = reportService.generateRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());
222	            ctx.contentType("text/csv; charset=utf-8").result(csv);
223	        } catch (DateTimeParseException e) {
224	            throw new InvalidRequestException("Formato de mês inválido");
225	        }
226	    }
227	
228	    private Map<String, Object> toReservationResponse(Reservation r) {
229	        return Map.ofEntries(
230	            Map.entry("id", r.getId()),
231	            Map.entry("roomNumber", r.getRoomNumber()),
232	            Map.entry("guestName", r.getGuestName()),
233	            Map.entry("guestEmail", r.getGuestEmail()),
234	            Map.entry("guestCpf", r.getGuestCpf()),
235	            Map.entry("checkIn", r.getCheckIn().toString()),
236	            Map.entry("checkOut", r.getCheckOut().toString()),
237	            Map.entry("guests", r.getGuests()),
238	            Map.entry("ratePlan", r.getRatePlanType().name()),
239	            Map.entry("nights", r.getNights()),
240	            Map.entry("subtotal", r.getSubtotal()),
241	            Map.entry("discount", r.getDiscount()),
242	            Map.entry("total", r.getTotal()),
243	            Map.entry("status", r.getStatus().name()),
244	            Map.entry("amountPaid", r.getAmountPaid()),
245	            Map.entry("refund", r.getRefund())
246	        );
247	    }
248	
249	    private Map<String, Object> toDocumentResponse(Reservation r) {
250	        String roomType = switch (r.getRoomNumber()) {
251	            case "101", "102" -> "STANDARD";
252	            case "201", "202" -> "DELUXE";
253	            case "301" -> "SUITE";
254	            default -> "";
255	        };
256	
257	        Map<String, Object> map = new LinkedHashMap<>();
258	        map.put("title", "Comprovante de reserva");
259	        map.put("reservationId", r.getId());
260	        map.put("guestName", r.getGuestName());
261	        map.put("guestCpf", r.getGuestCpf());
262	        map.put("roomNumber", r.getRoomNumber());
263	        map.put("roomType", roomType);
264	        map.put("checkIn", r.getCheckIn().toString());
265	        map.put("checkOut", r.getCheckOut().toString());
266	        map.put("nights", r.getNights());
267	        map.put("subtotal", r.getSubtotal());
268	        map.put("discount", r.getDiscount());
269	        map.put("total", r.getTotal());
270	        return map;
271	    }
272	
273	    private void validateRequiredFields(Map<String, Object> body, String... fields) {
274	        for (String field : fields) {
275	            if (!body.containsKey(field) || body.get(field) == null) {
276	                throw new InvalidRequestException("Campo obrigatório ausente: " + field);
277	            }
278	        }
279	    }
280	
281	    private LocalDate parseDate(String dateStr) {
282	        try {
283	            return LocalDate.parse(dateStr);
284	        } catch (DateTimeParseException e) {
285	            throw new InvalidRequestException("Formato de data inválido");
286	        }
287	    }
288	
289	    private void sendError(Context ctx, int status, String errorCode, String message) {
290	        ctx.status(status).json(Map.of(
291	            "error", errorCode,
292	            "message", message
293	        ));
294	    }
295	}

