     1	package com.pousada.domain.rateplan;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public abstract class AbstractRatePlan implements RatePlan {
     9	
    10	    protected BigDecimal roundMoney(BigDecimal amount) {
    11	        return amount.setScale(2, RoundingMode.HALF_EVEN);
    12	    }
    13	
    14	    protected boolean isHighSeason(LocalDate date) {
    15	        Month month = date.getMonth();
    16	        int day = date.getDayOfMonth();
    17	
    18	        if (month == Month.DECEMBER && day >= 15) {
    19	            return true;
    20	        }
    21	
    22	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    23	            return true;
    24	        }
    25	
    26	        if (month == Month.JULY) {
    27	            return true;
    28	        }
    29	
    30	        return false;
    31	    }
    32	
    33	    protected BigDecimal calculateNightPrice(BigDecimal nightlyRate, LocalDate night) {
    34	        BigDecimal price = nightlyRate;
    35	        if (isHighSeason(night)) {
    36	            price = price.multiply(new BigDecimal("1.20"));
    37	        }
    38	        return roundMoney(price);
    39	    }
    40	
    41	    protected int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    42	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    43	    }
    44	}
