    24	        BigDecimal subtotal = BigDecimal.ZERO;
    25	        LocalDate currentNight = checkIn;
    26	
    27	        while (currentNight.isBefore(checkOut)) {
    28	            BigDecimal nightPrice = calculateNightPrice(nightlyRate, currentNight);
    29	            subtotal = subtotal.add(nightPrice);
    30	            currentNight = currentNight.plusDays(1);
