    44	    public String buildReceipt(Reservation reservation) {
    45	        StringBuilder receipt = new StringBuilder();
    46	        receipt.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    47	        receipt.append("Hóspede: ").append(reservation.getGuestName())
    48	               .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    49	
    50	        String roomType = getRoomType(reservation.getRoomNumber());
    51	        receipt.append("Quarto: ").append(reservation.getRoomNumber())
    52	               .append(" (").append(roomType).append(")\n");
    53	
    54	        receipt.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMAT))
    55	               .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMAT))
    56	               .append(" | ").append(reservation.getNights())
    57	               .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
    58	
    59	        receipt.append("Diárias: ").append(MONEY_FORMAT.format(reservation.getSubtotal())).append("\n");
    60	
    61	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
    62	            receipt.append("Desconto: ").append(MONEY_FORMAT.format(reservation.getDiscount())).append("\n");
    63	        }
    64	
    65	        receipt.append("Total: ").append(MONEY_FORMAT.format(reservation.getTotal()));
    66	
    67	        return receipt.toString();
    68	    }
