    23	    public Reservation createReservation(Reservation reservation) {
    24	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
    25	            .orElseThrow(() -> new RoomNotFoundException("Quarto não encontrado"));
    26	
    27	        validateReservation(reservation, room);
    28	
    29	        reservation.calculatePricing(room.getNightlyRate());
    30	
    31	        return reservationRepository.save(reservation);
    32	    }
    33	
    34	    private void validateReservation(Reservation reservation, Room room) {
    35	        if (reservation.getCheckOut().isBefore(reservation.getCheckIn()) ||
    36	            reservation.getCheckOut().equals(reservation.getCheckIn())) {
    37	            throw new InvalidRequestException("Data de saída deve ser posterior à data de entrada");
    38	        }
    39	
    40	        if (reservation.getGuests() < 1) {
    41	            throw new InvalidRequestException("Número de hóspedes deve ser no mínimo 1");
    42	        }
    43	
    44	        if (reservation.getGuests() > room.getCapacity()) {
    45	            throw new CapacityExceededException("Número de hóspedes excede a capacidade do quarto");
    46	        }
    47	
    48	        RatePlan ratePlan = reservation.getRatePlanType().create();
    49	        try {
    50	            ratePlan.validate(reservation.getCheckIn(), reservation.getCheckOut(), reservation.getCompanyCode());
    51	        } catch (IllegalArgumentException e) {
    52	            throw new InvalidRequestException(e.getMessage());
    53	        }
    54	
    55	        List<Reservation> conflictingReservations = reservationRepository.findByRoomAndDateRange(
    56	            reservation.getRoomNumber(),
    57	            reservation.getCheckIn(),
    58	            reservation.getCheckOut()
    59	        );
    60	
    61	        if (!conflictingReservations.isEmpty()) {
    62	            throw new RoomUnavailableException("Quarto já reservado para as datas selecionadas");
    63	        }
    64	    }
